  /* ============================================================
   * pages/dashboard.html · 鉴定台总览
   * ------------------------------------------------------------
   * 属名一律「拉丁属名 (+ genus)」：中文的「属」是分类阶元标记，
   * 英文里靠属名本身表达（Baetis 就是属），加 (genus) 只是给
   * 不熟悉拉丁名的读者一个提示，避免和同名的「种」条目混淆。
   * ============================================================ */
